// src/components/ui/accordion.jsx

"use client"

import * as React from "react";
import * as AccordionPrimitive from "@radix-ui/react-accordion";
import { ChevronDown } from "lucide-react"; // lucide-react madhun icon import kela
import PropTypes from 'prop-types'; // PropTypes add kele

import { cn } from '../../lib/utils'; // Tumchya utils file cha path

// ===== Main Accordion Wrapper =====
const Accordion = React.forwardRef(({ className, ...props }, ref) => (
    // TypeScript types kadhun takle
    <AccordionPrimitive.Root
        ref={ref}
        className={cn("w-full", className)}
        {...props}
    />
));
Accordion.displayName = AccordionPrimitive.Root.displayName;

// ===== Accordion Item (Each collapsible section) =====
const AccordionItem = React.forwardRef(({ className, ...props }, ref) => (
    <AccordionPrimitive.Item
        ref={ref}
        className={cn("border-b", className)}
        {...props}
    />
));
AccordionItem.displayName = "AccordionItem";

// ===== Accordion Trigger (The clickable header) =====
const AccordionTrigger = React.forwardRef(({ className, children, ...props }, ref) => (
    <AccordionPrimitive.Header className="flex">
        <AccordionPrimitive.Trigger
            ref={ref}
            className={cn(
                "flex flex-1 items-center justify-between py-4 font-medium transition-all hover:underline [&[data-state=open]>svg]:rotate-180",
                className
            )}
            {...props}
        >
            {children}
            <ChevronDown className="h-4 w-4 shrink-0 transition-transform duration-200" />
        </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = AccordionPrimitive.Trigger.displayName;

// ===== Accordion Content (The collapsible content area) =====
const AccordionContent = React.forwardRef(({ className, children, ...props }, ref) => (
    <AccordionPrimitive.Content
        ref={ref}
        className="overflow-hidden text-sm transition-all data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down"
        {...props}
    >
        <div className={cn("pb-4 pt-0", className)}>{children}</div>
    </AccordionPrimitive.Content>
));
AccordionContent.displayName = AccordionPrimitive.Content.displayName;


// --- PropTypes ---
Accordion.propTypes = {
    className: PropTypes.string,
};

AccordionItem.propTypes = {
    className: PropTypes.string,
    value: PropTypes.string.isRequired, // 'value' prop आवश्यक आहे
};

AccordionTrigger.propTypes = {
    className: PropTypes.string,
    children: PropTypes.node.isRequired,
};

AccordionContent.propTypes = {
    className: PropTypes.string,
    children: PropTypes.node.isRequired,
};


export { Accordion, AccordionItem, AccordionTrigger, AccordionContent }